sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    var userName = request.pathParams.user_name;
    var query = request.queryParams.ni_query;

    gs.info('NI Get Info Operation Script called for user: ' + userName + ' with query: ' + query, 'NI_GetInfo');

    var userRecord = new GlideRecord('sys_user');
    userRecord.get('user_name', userName);

    if (!userRecord.user_name) {
        var apiError = new sn_ws_err.ServiceError();
        apiError.setMessage('User Name is required');
        apiError.setDetail('The user_name path parameter must be provided.');
        response.setStatus(400);
        response.setError(apiError);
        return;
    }

    var activeNeeditCount = new GlideAggregate('x_58872_needit_needit');
    activeNeeditCount.addAggregate('COUNT');
    activeNeeditCount.addQuery('u_requested_for', userRecord.sys_id);
    activeNeeditCount.addEncodedQuery(query); // 'active=true'
    activeNeeditCount.groupBy('u_request_type');
    activeNeeditCount.query();

    var needitRecords = 0;
    var userNeeditRecords = [];
    var needitRecordsCount = 0;

    while (activeNeeditCount.next()) {
        needitRecords = activeNeeditCount.getAggregate('COUNT');
        var requestType = activeNeeditCount.u_request_type.getDisplayValue();
        userNeeditRecords.push({
            'RequestType': requestType,
            'NeeditCount': needitRecords
        });
        needitRecordsCount += parseInt(needitRecords, 10);
    }

    var body = {
        totalNeeditCount: needitRecordsCount,
        needitByRequestType: userNeeditRecords,
        user: {
            'UserName': userRecord.user_name,
            'UserID': userRecord.sys_id
        }
    };

    response.setBody(body);


})(request, response);
